const $=id=>document.getElementById(id);let current=null;let saved=[];try{saved=JSON.parse(localStorage.getItem('worth-reflections')||'[]');if(!Array.isArray(saved))saved=[]}catch{}const levels=['Very little','Light','Moderate','A lot','Almost everything'];const capacities=['Running on empty','Low reserves','Some room','Feeling steady','Plenty to give'];function ranges(){$('energyOut').textContent=levels[$('energy').value-1];$('capacityOut').textContent=capacities[$('capacity').value-1]}['energy','capacity'].forEach(id=>$(id).addEventListener('input',ranges));function put(id,text){$(id).textContent=text}function persist(){try{localStorage.setItem('worth-reflections',JSON.stringify(saved));return true}catch{return false}}function render(){const list=$('entries');list.replaceChildren();$('noSaved').hidden=saved.length>0;saved.slice().reverse().forEach(item=>{const row=document.createElement('div');row.className='entry';const body=document.createElement('div');body.className='body';const b=document.createElement('b');b.textContent=item.task;const small=document.createElement('small');small.textContent=`${new Date(item.date).toLocaleDateString()} · ${item.outcome||'Waiting to see how it felt'}`;body.append(b,small);if(item.next){const p=document.createElement('p');p.textContent=item.next;body.append(p)}const select=document.createElement('select');select.style.width='auto';select.setAttribute('aria-label','How did '+item.task+' turn out?');['Reflect afterward…','Worth the effort','Mixed feelings','Too much for today','Chose the alternative'].forEach((v,i)=>{const o=new Option(v,i?v:'');select.add(o)});select.value=item.outcome||'';select.onchange=()=>{item.outcome=select.value;if(!persist())alert('Could not save in this browser.');render()};const del=document.createElement('button');del.className='quiet';del.textContent='Delete';del.onclick=()=>{saved=saved.filter(x=>x.id!==item.id);persist();render()};row.append(body,select,del);if(item.profileSummary){const details=document.createElement('details');const title=document.createElement('summary');title.textContent='View expectations and reflect';const forecast=document.createElement('p');forecast.textContent=item.profileSummary;const note=document.createElement('textarea');note.placeholder='What actually happened? How did you feel and how much effort did it take?';note.setAttribute('aria-label','Reflection on '+item.task);note.value=item.actualReflection||'';const saveNote=document.createElement('button');saveNote.className='quiet';saveNote.textContent='Save follow-up';const status=document.createElement('span');status.setAttribute('role','status');saveNote.onclick=()=>{item.actualReflection=note.value;status.textContent=persist()?' Follow-up saved.':' Could not save in this browser.'};details.append(title,forecast,note,saveNote,status);row.append(details)}list.append(row)})}
$('form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(['task','alt','minutes','money','energy','capacity','gain','skip','repeat'].map(id=>[id,$(id).value.trim()]));current=d;$('empty').hidden=true;$('result').hidden=false;put('doTitle',d.task);put('altTitle',d.alt);put('doGain',d.gain);put('skipText',d.skip);put('cost',`${d.minutes} minutes · $${Number(d.money||0).toFixed(2)} · ${levels[d.energy-1].toLowerCase()} intensity`);const gap=Number(d.energy)-Number(d.capacity);put('summary',gap>0?'The effort you expect is higher than the energy you have today. That is one important part of the tradeoff.':gap===0?'The effort you expect matches the energy you have today. Consider what you would have left afterward.':'You expect to have some energy left afterward. The benefit and the alternative still matter.');const freq=d.repeat==='daily'?7:1;put('recurrence',d.repeat==='once'?'This is one decision for today. It does not have to become a rule for every day.':`At this pace, that's about ${Number((d.minutes*freq/60).toFixed(1))} hours and $${(Number(d.money||0)*freq).toFixed(2)} each week. Is that a rhythm you want to keep?`);put('question',gap>0?'Is there a smaller version that keeps the most important benefit while taking less energy?':d.repeat!=='once'?'What have previous times taught you about whether the benefit lasts beyond the effort?':'Which consequence of choosing the alternative would be hardest to undo—and could you check how likely it is?');$('next').value='';$('save').disabled=false;put('saveMessage','Saved reflections stay in this browser.');if(innerWidth<760)$('result').scrollIntoView({behavior:'smooth',block:'start'})};$('example').onclick=()=>{const ex={task:'Go to class today',alt:'Rest, then watch the recording',minutes:150,money:6,energy:4,capacity:2,gain:'Understand the new material and ask questions in person.',skip:'I would need to catch up tomorrow. I still need to check whether attendance counts.',repeat:'weekly'};Object.entries(ex).forEach(([k,v])=>$(k).value=v);ranges();$('form').requestSubmit()};$('reset').onclick=()=>{$('form').reset();ranges();current=null;$('empty').hidden=false;$('result').hidden=true;$('task').focus()};$('save').onclick=()=>{if(!current)return;saved.push({...current,id:crypto.randomUUID(),date:new Date().toISOString(),next:$('next').value.trim()});if(persist()){put('saveMessage','Saved. Come back to note how it turned out.');$('save').disabled=true;render()}else{saved.pop();put('saveMessage','Storage is unavailable. This reflection could not be saved.')}};$('journalBtn').onclick=()=>$('journal').scrollIntoView({behavior:'smooth'});render();
